-- NNvastgoed — ALLE testgegevens verwijderen (hoort bij testdata.sql en testdata_recreatie.sql).
-- Raakt alleen de testkantoren, de testwoningen (ook losse recreatiewoningen bij een eigen kantoor) en de accounts op @nnv.test.
-- Jouw eigen account, je eigen kantoren en je eigen woningen blijven staan.

delete from saved_searches where email like '%@nnv.test';
delete from broker_requests where email like '%@nnv.test';
delete from usage_events where unique_key like 'testdata:%';
delete from listings where slug in ('nieuwe-ebbingestraat-34-groningen', 'hereweg-112-groningen', 'vinkenstraat-9-groningen', 'meerweg-27-groningen', 'stationsweg-3-veendam', 'hoofdstraat-41-uithuizen', 'dijkweg-2-roodeschool', 'hoofdweg-88-winsum', 'burchtstraat-14-appingedam', 'nieuwestad-57-leeuwarden', 'oldehoofsterkerkhof-5-leeuwarden', 'prof-dr-j-w-de-langestraat-19-leeuwarden', 'harlingerstraatweg-7-dronrijp', 'kleine-kerkstraat-6-sneek', 'kuilstraat-22-joure', 'zuiderhaven-1-harlingen', 'heerenveenseweg-5-bolsward', 'lemsterhoek-12-lemmer', 'brinkstraat-31-assen', 'kerkstraat-4-roden', 'zuidlaarderweg-16-zuidlaren', 'industrieweg-3-assen', 'dorpsstraat-55-grolloo', 'hoofdstraat-18-emmen', 'weiersstraat-21-coevorden', 'de-stoep-7-hoogeveen', 'beilerstraat-1-beilen', 'zuiderdiep-30-dalen', 'dokkumerdiep-8-dokkum', 'oosterstraat-88-groningen', 'paterswoldseweg-45-groningen', 'gedempte-zuiderdiep-9-leeuwarden', 'havenstraat-14-joure', 'torenlaan-3-assen', 'marktstraat-31-emmen', 'meerstad-zuid-kavel-12-groningen', 'meerstad-zuid-kavel-14-groningen', 'zuiderburen-5-leeuwarden', 'kloosterveen-fase-4-nr-6-assen', 'nieuw-weerdinge-8-emmen', 'eemskade-2-groningen', 'industrieweg-41-sneek', 'hoofdstraat-70-uithuizen', 'weiersstraat-6-coevorden', 'marsdijk-12-assen', 'oudemirdumerklif-12-oudemirdum', 'waddendijk-4-paesens-moddergat', 'oostergoweg-21-langweer', 'havenweg-3-lauwersoog', 'bosweg-8-diever', 'hunebedweg-15-borger', 'veenpad-2-erica', 'zeedijk-10-zoutkamp', 'burg-reedekerstraat-9-west-terschelling', 'zuiderpark-8-groningen', 'kerkstraat-21-haren', 'wierdeweg-7-usquert', 'molenweg-3-winschoten', 'zuidergrachtswal-12-leeuwarden', 'bonifatiusplein-1-leeuwarden', 'oudvaart-14-sneek', 'gieterstraat-9-gieten', 'plantsoen-4-meppel', 'hoofdstraat-61-hoogeveen', 'verlengde-stationsweg-2-emmen', 'dijkweg-1-makkum', 'hoofdweg-5-hollum', 'reeweg-8-schiermonnikoog', 'strandweg-2-lauwersoog', 'wijkweg-3-dwingeloo', 'meerweg-4-heeg', 'heidepad-6-gasselte');                  -- ook testwoningen die bij een eigen kantoor staan; leads, bezichtigingen en gesprekken volgen mee
delete from offices where id in ('a0000001-0000-4000-8000-000000000001', 'a0000001-0000-4000-8000-000000000002', 'a0000001-0000-4000-8000-000000000003', 'a0000001-0000-4000-8000-000000000004', 'a0000001-0000-4000-8000-000000000005', 'a0000001-0000-4000-8000-000000000006');   -- woningen, leads, bezichtigingen, gesprekken, beschikbaarheid en koppelingen volgen mee
delete from auth.users where email like '%@nnv.test';          -- profielen en favorieten volgen mee

select (select count(*) from offices) as kantoren_over, (select count(*) from listings) as woningen_over, (select count(*) from auth.users) as accounts_over;
